  public void initCommandProducer(
      org.tura.platform.repository.jpa.operation.EntityManagerProvider emProvider,
      java.util.Map<String, ExternalQueryProcessor<?>> queryProcessorRegistry) {
    registry.addCommandProducer(
        "persistence-repository",
        org.tura.platform.repository.jpa.operation.JpaCommandProducer.class);
    spaRegistry
        .getRegistry("persistence-repository")
        .addExternalCommand(
            org.tura.platform.repository.jpa.operation.JpaExternalConnectDetailToMasterOperation
                .class);
    spaRegistry
        .getRegistry("persistence-repository")
        .addExternalCommand(
            org.tura.platform.repository.jpa.operation.JpaExternalConnectMasterToDetailOperation
                .class);
    spaRegistry
        .getRegistry("persistence-repository")
        .addExternalCommand(
            org.tura.platform.repository.jpa.operation
                .JpaExternalDisconnectDetailFromMasterOperation.class);
    spaRegistry
        .getRegistry("persistence-repository")
        .addExternalCommand(
            org.tura.platform.repository.jpa.operation
                .JpaExternalDisconnectMasterFromDetailOperation.class);
    spaRegistry
        .getRegistry("persistence-repository")
        .addInstantiator(new JpaOperationsInstantiator(registry, spaRegistry));
    JpaServiceInstantiator jpaServiceInstantiator =
        new JpaServiceInstantiator(spaRegistry, "persistence-repository", registry, emProvider);
    jpaServiceInstantiator.addExternalQueryProcessor(queryProcessorRegistry);
    spaRegistry.getRegistry("persistence-repository").addInstantiator(jpaServiceInstantiator);
  }

  public void initRules() {
    registry.addRule(
        org.tura.platform.repository.core.navigation.NavigationRuleTypes
            .AddObject_ValidateIsObjectContainment.name(),
        org.tura.platform.repository.core.navigation.AddObjectsDefaultRule.class);
  }

